330	    protected function publicationData($request)
331	    {
332	
333	        $public = !empty($request['publication_status']) ? $request['publication_status'] : '';
334	
335	        $formatDate = 'Y-m-d';
336	        $formatDateTime = 'Y-m-d H:i:s';
