338	        if (isset($request["date_start"]) && strlen($request["date_start"]) > 10) {
339	            $formatType = 2;
340	        }
341	        if (!isset($request["date_start"]) || !strlen($request["date_start"])) {
342	            $formatType = 2;
343	            $request['date_start'] = date($formatDateTime);
344	        }
345	
346	
347	        $date_start = !empty($request['date_start']) ? DateTime::createFromFormat(($formatType == 2 ? $formatDateTime : $formatDate), $request['date_start']) : '';
348	        $date_end = !empty($request['date_end']) ? DateTime::createFromFormat(($formatType == 2 ? $formatDateTime : $formatDate), $request['date_end']) : '';
349	
350	        $expiration = !empty($request['depublication_status'])  && $request['depublication_status'] == 'Y' ? 'Y' : 'N';
351	
352	        switch($public) {
353	            case 'Y': $public = 'Y';
354	                $date_start = new DateTime();
355	                break;
356	            case 'A': $public = 'Y';
357	                $date_start = $date_start ? $date_start : new DateTime();
358	                break;
359	            case 'N': $public = 'N';
360	                $date_start = new DateTime();
361	                break;
362	            default: $public = 'Y';
363	                $date_start = new DateTime();
364	                break;
365	        }
